"""Editorial assessments, whole-film coverage and offline review catalog."""
import html
import json
from collections import Counter
from audit_spiderman_full import OUT,CHAPTERS,tc

# These are editorial hypotheses, not predictions of views or measured retention.
ROWS=[
('S01','strong',1602,1674,'Паутина не слушается Питера','Новая способность не срабатывает по команде.','Неудачные команды → находит жест → первый полёт и столкновение.','Зрительная комедия, понятная цель и ошибка героя.','Сохранить жест и траекторию; не превращать весь эпизод в набор прыжков.','30–45 с'),
('S02','strong',2128,2179,'Дядя Бен говорит о силе, Питер отталкивает его','Бен спорит с Питером о школьной драке.','Может избить ≠ имеет право → ответственность → резкий ответ и реакция Бена.','Конфликт и эмоциональный поворот внутри одной беседы.','Не выдавать афоризм за всю историю; сохранить ответ Питера и боль Бена.','40–50 с'),
('S03','strong',2306,2350,'Питеру придумывают имя Человек-паук','Ведущий спрашивает имя начинающего борца.','Неудачное имя → ведущий заменяет его → Питер возражает, но выходит на ринг.','Короткая законченная комедия; появление знакомого имени.','Концовка именно возражение Питера; не добавлять случайный удар из боя.','30–40 с'),
('S04','strong',1434,1506,'Флэш не знал о новых способностях Питера','Школьный задира угрожает тому, кто не хочет драться.','Угроза → неожиданное уклонение → ответный удар → реакции.','Понятный конфликт и физическая развязка.','Этот монтаж уже сделан. Новый вариант той же сцены не публиковать параллельно.','50–59 с'),
('S05','strong',2508,2576,'Организатор слышит собственное Не моя проблема','Победителю платят меньше обещанного.','Недоплата → отказ помочь → ограбление → Питер повторяет фразу организатора.','Симметричная реплика связывает завязку и развязку.','Это локальное возмездие, не моральная победа: позже фильм показывает цену решения. Этот монтаж уже сделан.','45–59 с'),
('S06','strong',3679,3741,'Джеймисон ругает снимки, но тут же покупает','Редактор обесценивает работу начинающего фотографа.','Плохие фото → торг → снимки на первую полосу → отказ в штатной работе.','Ясная бытовая ставка: деньги и работа; несколько смен позиции.','Убрать отвлечения про шторы только между целыми репликами; оставить оплату и решение.','40–59 с'),
('S07','strong',3765,3847,'Нормана увольняют из собственной компании','Норман отчитывается о рекордной прибыли.','Успех → совет продаёт фирму → условие ухода → Ты уволен.','Предательство понятно без знания супергеройской линии.','Не вырезать первую реплику об успехе: без неё теряется переворот.','45–59 с'),
('S08','strong',4341,4454,'Норман понимает, с кем разговаривает','Невидимый собеседник знает о его поступках.','Поиск голоса → отражение → Ты их убил / Мы их убили.','Загадка с видимым раскрытием и сильной актёрской игрой.','Тёмные кадры и длинные паузы; финал на признании, а не на новом монологе о союзе.','45–59 с'),
('S09','strong',4502,4534,'Джеймисон не выдаёт фотографа Гоблину','Гоблин требует назвать человека, который снимает Паука.','Прямая угроза → редактор врёт, защищая источник → вмешательство героя.','Неожиданная черта персонажа, которого до этого видели грубым.','Одной плашкой объяснить, что редактор знает фотографа; не вставлять предыдущий торг ради узнаваемости.','25–35 с'),
('S10','strong',4994,5066,'В горящем доме остался не тот, кого он ожидал','После спасения ребёнка сообщают о ещё одном человеке.','Герой возвращается → фигура просит помощи → раскрывается Гоблин → отказ от союза.','Настоящий сюжетный обман и ответ героя.','Не заканчивать на фигуре под покрывалом; показать раскрытие и ответ.','45–59 с'),
('S11','strong',5268,5331,'Норман узнаёт Паука по ране за ужином','Тётя замечает кровь на руке Питера.','Объяснение Питера → взгляд Нормана → узнавание → внезапный уход.','Деталь превращается в разоблачение, рассказ держится на реакциях.','Нужен краткий визуальный контекст происхождения раны или понятная плашка; иначе непонятно, что понял Норман.','40–59 с'),
('S12','strong',6472,6579,'Последняя уловка Нормана','Побеждённый Норман снимает маску и просит защиты.','Попытка заменить Бена → Питер отказывает → скрытая атака планером → собственная ловушка.','Убедительная манипуляция и зримое опровержение слов действием.','Нельзя вырезать подготовку планера. Смерть лучше обозначить реакцией, без акцента на травме.','50–75 с'),
('R01','reserve',1321,1354,'Питер ловит поднос, но теряется в разговоре','Мэри Джейн поскальзывается рядом с Питером.','Падение → ловля вещей → комплимент глазам → неловкое прощание.','Лёгкая и понятная миниатюра; уже сделана как отдельный монтаж.','Слабее конфликт, чем у S04/S05; не считать красивый трюк достаточным доказательством сильного удержания.','25–35 с'),
('R02','reserve',1070,1172,'Утро после укуса','Питер просыпается после болезни.','Зрение и тело изменились → зеркало → неожиданная бытовая сила.','Видимая перемена и узнаваемая ситуация.','Много немых проверок; не соединять произвольно с более поздним боем и не пересказывать весь генезис героя.','30–45 с'),
('R03','reserve',1798,1887,'Питер первым поверил в мечту Мэри Джейн','Она стесняется сказать, кем хочет стать.','Признание мечты → поддержка Питера → детское воспоминание → ответ о Бродвее.','Тёплая история вместо очередной угрозы.','Тёмная картинка и тихий разговор; нужен зритель, которому интересны персонажи.','40–59 с'),
('R04','reserve',4828,4887,'Спасибо под дождём','Спасённая девушка останавливает героя перед уходом.','Шутка о спасениях → просьба поблагодарить → поцелуй.','Узнаваемая романтическая развязка.','Вырванный поцелуй без спасения становится просто известным кадром; нужно решить, сохраняем ли короткий контекст.','35–50 с'),
('R05','reserve',6089,6310,'Выбрать девушку или детей','Гоблин держит двух заложников одновременно.','Ложная дилемма → Питер спасает обе стороны → горожане помогают.','Самые высокие ставки и наглядное действие.','Почти четыре минуты исходника и сложная география. Не обещать законченные 30 секунд; сначала отдельная сборка 75–120 с.','75–120 с'),
('R06','reserve',6710,6878,'Она признаётся, он обещает только дружбу','Мэри Джейн говорит, что думала о Питере перед смертью.','Признание → взаимное чувство → отказ ради её безопасности.','Эмоциональная перемена и горькая развязка.','Зависит от полного контекста угрозы близким; длинная сцена на кладбище, не первая партия.','60–90 с'),
('W01','weak',386,444,'Экскурсия: разновидности пауков','Экскурсовод объясняет свойства пауков.','Перечисление свойств без локального решения или конфликта.','Полезный материал для контекста происхождения сил.','Как отдельный Short — лекция без выплаты обещания; не монтировать только ради знакомого фильма.','не делать отдельно'),
('W02','weak',654,748,'Разговор о финансировании лаборатории','Военные требуют результат и угрожают забрать контракт.','Технический отчёт и ультиматум.','Мотивирует будущий эксперимент Нормана.','Слишком много терминов и имён для холодного зрителя; эксперимент отдельно выразительнее.','контекст, не отдельный ролик'),
('W03','weak',3047,3115,'Поздравления на выпускном','Персонажи поздравляют друг друга и обсуждают будущее.','Поздравление → семейные реплики → переход к следующей линии.','Связка внутри полнометражного повествования.','Нет самостоятельного вопроса и неожиданного ответа; сильные лица не заменяют историю.','не делать отдельно'),
('W04','weak',3271,3349,'Город обсуждает нового героя','Разные жители по-разному говорят о Человеке-пауке.','Несколько несвязанных мнений и спасений.','Можно использовать как короткий контекст общественной реакции.','Повторит проблему случайных вставок, если собрать отдельный ролик без выбранной линии.','только как контекст'),
]


def build():
    data=[]
    for rid,tier,a,b,title,hook,arc,strength,risk,length in ROWS:
        data.append(dict(id=rid,tier=tier,start=a,end=b,title=title,hook=hook,arc=arc,
            strength=strength,risk=risk,target=length,approval='not_approved'))
    (OUT/'candidates.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
    labels={'strong':'Сильный','reserve':'Резерв','weak':'Слабый отдельно'}
    intro=['# Человек-паук (2002): полный редакторский разбор','',
        '**Сначала согласование, затем публикация. Все кандидаты ниже не согласованы.**','',
        'Проверены все 16 глав исходника длительностью 2:01:11, включая финал и титры: прочитаны русские встроенные субтитры, просмотрены 16 последовательных листов по 36 кадров (576 ориентиров по всему файлу). Это структурный разбор всего фильма, а не непрерывный просмотр со звуком. Встроенный перевод отличается от дубляжа; для финальных подписей требуется распознавание выбранных фрагментов.','',
        'Отобраны **12 сильных кандидатов, 6 резервных и 4 слабых как самостоятельные Shorts**. Это редакторские оценки, не прогноз просмотров. Все 22 сцены нарезаны в локальные просмотровые MP4 с оригинальным звуком, без декоративного монтажа и без загрузки. Границы пока контекстные: точные входы/выходы и длительность финальных роликов выбираются после согласования.','',
        'Для первого выбора рекомендую **S03 (имя), S06 (торг), S07 (увольнение), S09 (защита фотографа), S10 (ловушка в огне), S11 (рана за ужином)**. Здесь разные ситуации с явным поворотом; это не шесть похожих разговоров об угрозах.','',
        '[Открыть каталог с фильтрами и просмотром](index.html) · [Плейлист всех кандидатов](ALL_CANDIDATES.m3u8)','',
        'Все 22 просмотровых файла полностью декодированы; проверены длительность, наличие звука и локальные ссылки каталога. [Результаты проверки](verification.json). Общий размер просмотровых нарезок — около 111 МиБ.','',
        'Три уже готовых монтажа — S04, S05 и R01. Не считать их эталоном или повторно публиковать варианты: теперь они входят в общий отбор на тех же основаниях.','',
        '## Важное: прежнее расписание','',
        'Три несогласованных загрузки 9gERa0SrS_Y, jf8D7Af8VJY, ytDbbaePaa0 всё ещё назначены на 10 ноября, 09:00 / 13:00 / 17:00 МСК. Попытка снять расписание через API вернула 403 insufficient authentication scopes. Требуется отменить его в YouTube Studio либо расширить права подключения. Здесь отмена не подтверждена. Локальный загрузчик Spider-Man заблокирован до отдельного согласования.','',
        '## Каталог сцен','',
        '| ID | Оценка | Интервал исходника | История | План итоговой длины |',
        '|---|---|---|---|---|']
    for c in data:
        intro.append(f"| {c['id']} | {labels[c['tier']]} | {tc(c['start'])}–{tc(c['end'])} | [{c['title']}](previews/{c['id']}.mp4) | {c['target']} |")
    for c in data:
        intro.extend(['',f"### {c['id']}. {c['title']}",'',f"**{labels[c['tier']]} · {tc(c['start'])}–{tc(c['end'])}**",'',
            f"Завязка: {c['hook']}",f"\nИстория: {c['arc']}",f"\nСильная сторона: {c['strength']}",f"\nОграничение: {c['risk']}"])
    intro.extend(['','## Покрытие фильма','',
        'Листы — навигация с приблизительными метками времени, не доказательство просмотра каждого кадра. Конечные титры не предлагаются как отдельная история.'])
    for i,(a,b,title) in enumerate(CHAPTERS,1):
        intro.append(f"- {tc(a)}–{tc(b)}: {title} — [кадры](chapters/{i:02}.jpg), [реплики](chapters/{i:02}.txt).")
    (OUT/'README.md').write_text('\n'.join(intro)+'\n',encoding='utf-8')
    cards=[]
    for c in data:
        e=lambda s:html.escape(str(s),quote=True)
        cards.append(f'''<article data-tier="{c['tier']}"><h2>{c['id']} · {e(c['title'])}</h2>
<p class="tag">{labels[c['tier']]} · {tc(c['start'])}–{tc(c['end'])} · итог: {e(c['target'])}</p>
<video controls preload="none" src="previews/{c['id']}.mp4"></video>
<p><b>Завязка:</b> {e(c['hook'])}</p><p><b>Развитие и ответ:</b> {e(c['arc'])}</p>
<p><b>За:</b> {e(c['strength'])}</p><p><b>Ограничение:</b> {e(c['risk'])}</p><p class="status">Не согласовано · не для публикации</p></article>''')
    doc='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Человек-паук — отбор сцен</title><style>body{font:16px/1.5 system-ui;background:#101318;color:#e8edf4;margin:0;padding:24px;max-width:1500px;margin:auto}h1{margin:0}header{margin-bottom:22px}nav{position:sticky;top:0;background:#101318;padding:12px 0;z-index:2;display:flex;gap:10px;flex-wrap:wrap}button,input{font:inherit;padding:9px;border:1px solid #566374;background:#222b37;color:white;border-radius:7px}button{cursor:pointer}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:20px}article{background:#1c2430;padding:18px;border-radius:12px}h2{font-size:21px;margin:0}video{width:100%;background:black;aspect-ratio:16/9}.tag,.status{color:#a8c3e1}.notice{background:#482b28;padding:15px;border-radius:8px}article[hidden]{display:none}a{color:#93caff}</style>
<header><h1>Человек-паук (2002): отбор историй</h1><p>12 сильных · 6 резервных · 4 слабых отдельно. Локальные просмотровые фрагменты с исходным звуком.</p><p>Разобраны субтитры и последовательные листы всех 16 глав. Непрерывного просмотра со звуком не было. Оценки — гипотезы для отбора, без обещаний просмотров.</p><p class="notice">Публикация только после согласования. Прежние 3 загрузки ещё требуют отмены расписания в Studio: API изменения статуса вернул 403. Новых загрузок нет.</p><a href="README.md">Подробный разбор</a> · <a href="ALL_CANDIDATES.m3u8">Плейлист</a></header>
<nav><button data-filter="all">Все 22</button><button data-filter="strong">Сильные 12</button><button data-filter="reserve">Резерв 6</button><button data-filter="weak">Слабые отдельно 4</button><input id="search" placeholder="Название или ID сцены"></nav><main>'''+''.join(cards)+'''</main><script>let tier='all';const q=document.querySelector('#search');function filter(){document.querySelectorAll('article').forEach(a=>{a.hidden=(tier!=='all'&&a.dataset.tier!==tier)||!a.textContent.toLowerCase().includes(q.value.toLowerCase());if(a.hidden)a.querySelector('video').pause()})}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{tier=b.dataset.filter;filter()});q.oninput=filter;document.querySelectorAll('video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('video').forEach(o=>{if(o!==v)o.pause()})));</script></html>'''
    (OUT/'index.html').write_text(doc,encoding='utf-8')
    playlist=['#EXTM3U']
    for c in data:playlist.extend([f"#EXTINF:{c['end']-c['start']},{c['id']} {c['title']}",f"previews/{c['id']}.mp4"])
    (OUT/'ALL_CANDIDATES.m3u8').write_text('\n'.join(playlist)+'\n',encoding='utf-8')
    print('CATALOG',len(data),dict(Counter(c['tier'] for c in data)))


if __name__=='__main__':build()
